namespace PremiereCalendar.Services;

public static class CachedImageUrl
{
    /// <summary>Width of the poster variant requested by calendar cards and pre-generated by the poster warm-up queue.</summary>
    public const int PosterWidth = 185;

    /// <summary>Widths the application requests; anything else is snapped to the nearest of these.</summary>
    public static IReadOnlyList<int> AllowedWidths { get; } = [PosterWidth];

    private static readonly HashSet<string> RasterContentTypes = new(StringComparer.OrdinalIgnoreCase)
    {
        "image/jpeg", "image/png", "image/gif", "image/webp", "image/avif"
    };

    /// <summary>Returns the nearest allowed width for a positive request, or null when no variant was requested.</summary>
    public static int? SnapWidth(int? requested)
    {
        if (requested is not > 0)
        {
            return null;
        }

        var nearest = AllowedWidths[0];
        foreach (var candidate in AllowedWidths)
        {
            if (Math.Abs(candidate - requested.Value) < Math.Abs(nearest - requested.Value))
            {
                nearest = candidate;
            }
        }

        return nearest;
    }

    /// <summary>Normalizes a stored content type and accepts only the raster formats the endpoint may serve.</summary>
    public static bool TryGetRasterContentType(string? contentType, out string normalized)
    {
        normalized = (contentType ?? "").Split(';')[0].Trim().ToLowerInvariant();
        return RasterContentTypes.Contains(normalized);
    }

    public static string Build(string sourceUrl, string? version = null, int? width = null)
    {
        var path = $"/cached-image?url={Uri.EscapeDataString(sourceUrl)}";

        if (width is > 0)
        {
            path += $"&w={width.Value}";
        }

        if (!string.IsNullOrWhiteSpace(version))
        {
            path += $"&v={Uri.EscapeDataString(version)}";
        }

        return path;
    }
}
